'use strict';
const test = require('node:test');
const assert = require('node:assert');
const { capitalize, truncate, slugify } = require('./strings.js');

test('lowercases and turns spaces into hyphens', () => {
  assert.strictEqual(slugify('Hello World'), 'hello-world');
});

test('strips accents via unicode normalization', () => {
  assert.strictEqual(slugify('Cr\u00e8me Br\u00fbl\u00e9e'), 'creme-brulee');
});

test('collapses separator runs and trims edge hyphens', () => {
  assert.strictEqual(slugify('  --Big   News!!  '), 'big-news');
});

test('existing helpers are untouched', () => {
  assert.strictEqual(capitalize('hi'), 'Hi');
  assert.strictEqual(truncate('abcdef', 4), 'abcd...');
});

